CREATE OR REPLACE FUNCTION public.apply_sale_effects() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item JSONB; tx_id UUID; should_apply BOOLEAN; qty_needed INT; product_name TEXT; updated_id UUID; stock_after INT; BEGIN should_apply:=(NEW.status IN ('paid','pending')) AND NOT NEW.stock_applied; IF should_apply THEN FOR item IN SELECT * FROM jsonb_array_elements(COALESCE(NEW.items,'[]'::jsonb)) LOOP IF NULLIF(item->>'product_id','') IS NOT NULL THEN qty_needed:=COALESCE((item->>'qty')::int,0); IF qty_needed<=0 THEN RAISE EXCEPTION 'La cantidad vendida debe ser mayor que cero' USING ERRCODE='22023'; END IF; UPDATE public.products SET stock=stock-qty_needed WHERE id=(item->>'product_id')::uuid AND business_id=NEW.business_id AND stock>=qty_needed RETURNING id,stock INTO updated_id,stock_after; IF updated_id IS NULL THEN SELECT name INTO product_name FROM public.products WHERE id=(item->>'product_id')::uuid AND business_id=NEW.business_id; RAISE EXCEPTION 'Stock insuficiente para "%": no hay % unidades disponibles',COALESCE(product_name,item->>'name'),qty_needed USING ERRCODE='check_violation'; END IF; INSERT INTO public.inventory_movements(business_id,product_id,quantity_delta,stock_before,stock_after,movement_type,reason,source_type,source_id) VALUES(NEW.business_id,updated_id,-qty_needed,stock_after+qty_needed,stock_after,'sale','Salida por venta','sale',NEW.id); END IF; END LOOP; IF NEW.transaction_id IS NULL AND NEW.total>0 THEN INSERT INTO public.transactions(business_id,type,category,amount,description,tx_date) VALUES(NEW.business_id,'income','Ventas',NEW.total,'Venta: '||COALESCE(NEW.customer_name,'Cliente'),NEW.sale_date) RETURNING id INTO tx_id; NEW.transaction_id:=tx_id; END IF; NEW.stock_applied:=true; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.apply_purchase_effects() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item JSONB; tx_id UUID; updated_id UUID; stock_after INT; qty_needed INT; BEGIN IF NEW.status IN ('received','paid') AND NOT NEW.stock_applied THEN FOR item IN SELECT * FROM jsonb_array_elements(COALESCE(NEW.items,'[]'::jsonb)) LOOP IF NULLIF(item->>'product_id','') IS NOT NULL THEN qty_needed:=COALESCE((item->>'qty')::int,0); IF qty_needed<=0 THEN RAISE EXCEPTION 'La cantidad comprada debe ser mayor que cero' USING ERRCODE='22023'; END IF; UPDATE public.products SET stock=stock+qty_needed WHERE id=(item->>'product_id')::uuid AND business_id=NEW.business_id RETURNING id,stock INTO updated_id,stock_after; IF updated_id IS NULL THEN RAISE EXCEPTION 'Producto de compra no encontrado en el negocio' USING ERRCODE='foreign_key_violation'; END IF; INSERT INTO public.inventory_movements(business_id,product_id,quantity_delta,stock_before,stock_after,movement_type,reason,source_type,source_id) VALUES(NEW.business_id,updated_id,qty_needed,stock_after-qty_needed,stock_after,'purchase','Entrada por compra','purchase',NEW.id); END IF; END LOOP; IF NEW.transaction_id IS NULL AND NEW.total>0 THEN INSERT INTO public.transactions(business_id,type,category,amount,description,tx_date) VALUES(NEW.business_id,'expense',COALESCE(NEW.category,'Otro'),NEW.total,'Compra: '||COALESCE(NEW.supplier_name,'Proveedor'),NEW.purchase_date) RETURNING id INTO tx_id; NEW.transaction_id:=tx_id; END IF; NEW.stock_applied:=true; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.revert_sale_effects() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item JSONB; v_before INT; v_after INT; v_product_id UUID; v_qty INT; BEGIN IF OLD.stock_applied THEN FOR item IN SELECT * FROM jsonb_array_elements(COALESCE(OLD.items,'[]'::jsonb)) LOOP IF NULLIF(item->>'product_id','') IS NOT NULL THEN v_product_id:=(item->>'product_id')::uuid; v_qty:=COALESCE((item->>'qty')::int,0); SELECT stock INTO v_before FROM public.products WHERE id=v_product_id AND business_id=OLD.business_id FOR UPDATE; IF v_before IS NULL THEN RAISE EXCEPTION 'Producto no encontrado al revertir venta' USING ERRCODE='foreign_key_violation'; END IF; v_after:=v_before+v_qty; UPDATE public.products SET stock=v_after WHERE id=v_product_id; INSERT INTO public.inventory_movements(business_id,product_id,quantity_delta,stock_before,stock_after,movement_type,reason,source_type,source_id) VALUES(OLD.business_id,v_product_id,v_qty,v_before,v_after,'sale_reversal','Reversión de venta','sale_reversal',OLD.id); END IF; END LOOP; IF OLD.transaction_id IS NOT NULL THEN DELETE FROM public.transactions WHERE id=OLD.transaction_id; END IF; END IF; RETURN OLD; END; $$;
CREATE OR REPLACE FUNCTION public.revert_purchase_effects() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item JSONB; v_before INT; v_after INT; v_product_id UUID; v_qty INT; BEGIN IF OLD.stock_applied THEN FOR item IN SELECT * FROM jsonb_array_elements(COALESCE(OLD.items,'[]'::jsonb)) LOOP IF NULLIF(item->>'product_id','') IS NOT NULL THEN v_product_id:=(item->>'product_id')::uuid; v_qty:=COALESCE((item->>'qty')::int,0); SELECT stock INTO v_before FROM public.products WHERE id=v_product_id AND business_id=OLD.business_id FOR UPDATE; IF v_before IS NULL OR v_before<v_qty THEN RAISE EXCEPTION 'No es posible revertir compra: stock insuficiente' USING ERRCODE='check_violation'; END IF; v_after:=v_before-v_qty; UPDATE public.products SET stock=v_after WHERE id=v_product_id; INSERT INTO public.inventory_movements(business_id,product_id,quantity_delta,stock_before,stock_after,movement_type,reason,source_type,source_id) VALUES(OLD.business_id,v_product_id,-v_qty,v_before,v_after,'purchase_reversal','Reversión de compra','purchase_reversal',OLD.id); END IF; END LOOP; IF OLD.transaction_id IS NOT NULL THEN DELETE FROM public.transactions WHERE id=OLD.transaction_id; END IF; END IF; RETURN OLD; END; $$;
CREATE OR REPLACE FUNCTION public.unapply_sale_on_cancel() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item JSONB; v_before INT; v_after INT; v_product_id UUID; v_qty INT; BEGIN IF OLD.stock_applied AND NEW.status='cancelled' AND OLD.status<>'cancelled' THEN FOR item IN SELECT * FROM jsonb_array_elements(COALESCE(OLD.items,'[]'::jsonb)) LOOP IF NULLIF(item->>'product_id','') IS NOT NULL THEN v_product_id:=(item->>'product_id')::uuid; v_qty:=COALESCE((item->>'qty')::int,0); SELECT stock INTO v_before FROM public.products WHERE id=v_product_id AND business_id=OLD.business_id FOR UPDATE; IF v_before IS NULL THEN RAISE EXCEPTION 'Producto no encontrado al cancelar venta' USING ERRCODE='foreign_key_violation'; END IF; v_after:=v_before+v_qty; UPDATE public.products SET stock=v_after WHERE id=v_product_id; INSERT INTO public.inventory_movements(business_id,product_id,quantity_delta,stock_before,stock_after,movement_type,reason,source_type,source_id) VALUES(OLD.business_id,v_product_id,v_qty,v_before,v_after,'sale_cancellation','Cancelación de venta','sale_cancellation',OLD.id); END IF; END LOOP; IF OLD.transaction_id IS NOT NULL THEN DELETE FROM public.transactions WHERE id=OLD.transaction_id; END IF; NEW.stock_applied:=false; NEW.transaction_id:=NULL; END IF; RETURN NEW; END; $$;
